properties.query:
let windowSize = 1h;

// S81: Fleet API Auth Bypass — UAVFleetInfra_CL엔 UAVId 없음, TargetId를 대리키로 사용
let S81 =
    UAVFleetInfra_CL
    | where TimeGenerated > ago(windowSize)
    | where IdorSuspected == true
    | extend Stage = 'S81', UAVId = tostring(TargetId)
    | where isnotempty(UAVId)
    | project TimeGenerated, Stage, UAVId;

// S82: Telemetry Poisoning — UAVFleetInfra_CL, Rule/ValueBefore/After
let S82 =
    UAVFleetInfra_CL
    | where TimeGenerated > ago(windowSize)
    | where isnotempty(Rule) and ValueBefore != ValueAfter
    | extend Stage = 'S82', UAVId = tostring(TargetId)
    | where isnotempty(UAVId)
    | project TimeGenerated, Stage, UAVId;

// S83: Imagery Stream Hijack — UAVFleetInfra_CL, HijackSuspected (UAVImagery_CL 아님)
let S83 =
    UAVFleetInfra_CL
    | where TimeGenerated > ago(windowSize)
    | where HijackSuspected == true
    | extend Stage = 'S83', UAVId = tostring(TargetId)
    | where isnotempty(UAVId)
    | project TimeGenerated, Stage, UAVId;

union S81, S82, S83
| summarize StagesSeen = make_set(Stage), StageCount = dcount(Stage), FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated) by UAVId
| where StageCount >= 2
| extend CampaignType = "C20_함대API우회_텔레메트리오염_영상하이재킹"
| extend StepSummary = strcat("Stages=", tostring(StagesSeen), " | First=", tostring(FirstSeen), " | Last=", tostring(LastSeen))
| extend Severity = "High"
| project FirstSeen, LastSeen, UAVId, StagesSeen, StageCount, CampaignType, StepSummary, Severity
